// Manual approach: explicit pull, create, start
// Step 1: Pull image from Docker Hub
// docker pull nginx:1.25

// Step 2: Create container without starting it
// docker create --name my-nginx -p 8080:80 nginx:1.25
// Output: container ID like 3f4e5a6b7c8d

// Step 3: Start the created container
// docker start my-nginx
// Output: my-nginx (container is now running)

// Automatic approach: docker run does all three steps
// docker run -d --name auto-nginx -p 8080:80 nginx:1.25
// Pulls image if not local, creates container, starts it immediately

// Verify both approaches result in same running state
// docker ps
// Shows both my-nginx and auto-nginx with STATUS "Up"

// In practice for Spring Boot
// docker run -d --name order-service -p 8080:8080 \
//   -e SPRING_PROFILES_ACTIVE=prod \
//   mycompany/order-service:1.2.3
// Automatically pulls mycompany/order-service:1.2.3 if missing
// Creates container with environment variable
// Starts Spring Boot app listening on port 8080

// Run Postgres with a named volume for database persistence
// docker run -d --name postgres-db -v pgdata:/var/lib/postgresql/data postgres:15

// Run Spring Boot app with volume for user file uploads
// docker run -d --name order-service -p 8080:8080 -v uploads:/app/uploads myapp:latest

@RestController
public class FileUploadController {
    private static final String UPLOAD_DIR = "/app/uploads";

    @PostMapping("/upload")
    public ResponseEntity<String> uploadFile(@RequestParam("file") MultipartFile file) {
        var targetPath = Path.of(UPLOAD_DIR, file.getOriginalFilename());
        // Write to /app/uploads inside container, actually goes to Docker volume
        Files.copy(file.getInputStream(), targetPath, StandardCopyOption.REPLACE_EXISTING);
        return ResponseEntity.ok("File saved: " + file.getOriginalFilename());
    }

    @GetMapping("/files")
    public List<String> listFiles() {
        // List persisted files from volume, survives container restart
        return Files.list(Path.of(UPLOAD_DIR))
                .map(path -> path.getFileName().toString())
                .toList();
    }
}
